route RootRoute { path: "/", to: MainPage }
page MainPage {
  component: import { MainPage } from "@src/MainPage"
}

route PostRoute { path: "/post/:postId", to: PostPage }
page PostPage {
  component: import { PostPage } from "@src/PostPage"
}

query getPosts {
  fn: import { getPosts } from "@src/queries.js",
  entities: [Post]
}

query getCommentTree {
  fn: import { getCommentTree } from "@src/queries.js",
  entities: [Post, Comment]
}

action createComment {
  fn: import { createComment } from "@src/actions.js",
  entities: [Comment, User, Post]
}

action deleteComment {
  fn: import { deleteComment } from "@src/actions.js",
  entities: [Comment]
}

export const getPosts = async (args, context) => {
  return context.entities.Post.findMany({
    select: {
      id: true,
      title: true,
    },
    orderBy: {
      id: 'asc',
    },
  });
};

export const getCommentTree = async (args, context) => {
  const { postId } = args;

  // Fetch all comments of this post ordered by id ascending
  const comments = await context.entities.Comment.findMany({
    where: { postId },
    include: {
      author: {
        select: { username: true },
      },
    },
    orderBy: {
      id: 'asc',
    },
  });

  // Build the tree map
  const commentMap = {};
  const rootComments = [];

  // Initialize nodes
  for (const comment of comments) {
    commentMap[comment.id] = {
      id: comment.id,
      content: comment.content,
      authorUsername: comment.author.username,
      parentId: comment.parentId,
      children: [],
    };
  }

  // Populate children
  for (const comment of comments) {
    const mapped = commentMap[comment.id];
    if (comment.parentId === null) {
      rootComments.push(mapped);
    } else {
      const parent = commentMap[comment.parentId];
      if (parent) {
        parent.children.push(mapped);
      }
    }
  }

  return rootComments;
};

export const createComment = async (args, context) => {
  const { postId, authorUsername, content, parentId } = args;

  // Look up user by username
  const user = await context.entities.User.findUnique({
    where: { username: authorUsername },
  });
  if (!user) {
    throw new Error(`User with username '${authorUsername}' not found`);
  }

  // Verify post exists
  const post = await context.entities.Post.findUnique({
    where: { id: postId },
  });
  if (!post) {
    throw new Error(`Post with id ${postId} not found`);
  }

  // If parentId is provided, verify comment exists
  if (parentId) {
    const parentComment = await context.entities.Comment.findUnique({
      where: { id: parentId },
    });
    if (!parentComment) {
      throw new Error(`Parent comment with id ${parentId} not found`);
    }
  }

  const newComment = await context.entities.Comment.create({
    data: {
      content,
      postId,
      authorId: user.id,
      parentId: parentId || null,
    },
  });

  return newComment;
};

export const deleteComment = async (args, context) => {
  const { commentId } = args;
  await context.entities.Comment.delete({
    where: { id: commentId },
  });
};

export const devSeed = async (prisma) => {
  // Idempotently create users
  await prisma.user.upsert({
    where: { username: 'alice' },
    update: {},
    create: { username: 'alice' },
  });

  await prisma.user.upsert({
    where: { username: 'bob' },
    update: {},
    create: { username: 'bob' },
  });

  // Idempotently create post
  const existingPost = await prisma.post.findFirst({
    where: { title: 'Wasp Nested Comments' },
  });

  if (!existingPost) {
    await prisma.post.create({
      data: {
        title: 'Wasp Nested Comments',
      },
    });
  }
};

import React, { useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { useQuery, getCommentTree, createComment, deleteComment } from 'wasp/client/operations';
import './Main.css';

// Recursive Comment Node Component
const CommentNode = ({ comment, postId, onReplyAdded, onDeleteDone }) => {
  const [showReplyForm, setShowReplyForm] = useState(false);
  const [replyContent, setReplyContent] = useState('');
  const [authorUsername, setAuthorUsername] = useState('alice');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleReplySubmit = async (e) => {
    e.preventDefault();
    if (!replyContent.trim()) return;
    setIsSubmitting(true);
    try {
      await createComment({
        postId,
        authorUsername,
        content: replyContent,
        parentId: comment.id,
      });
      setReplyContent('');
      setShowReplyForm(false);
      onReplyAdded();
    } catch (err) {
      alert(err.message || 'Failed to add reply');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDelete = async () => {
    if (window.confirm('Are you sure you want to delete this comment and all its replies?')) {
      try {
        await deleteComment({ commentId: comment.id });
        onDeleteDone();
      } catch (err) {
        alert(err.message || 'Failed to delete comment');
      }
    }
  };

  return (
    <div style={{ marginLeft: '20px', borderLeft: '2px solid #ddd', paddingLeft: '15px', marginTop: '15px' }} className="comment-node">
      <div className="comment-header" style={{ fontSize: '0.9rem', color: '#555', marginBottom: '4px' }}>
        <strong>{comment.authorUsername}</strong> <span style={{ color: '#999', fontSize: '0.8rem' }}>#{comment.id}</span>
      </div>
      <div className="comment-content" style={{ fontSize: '1rem', color: '#222', whiteSpace: 'pre-wrap', marginBottom: '8px' }}>
        {comment.content}
      </div>
      <div className="comment-actions" style={{ display: 'flex', gap: '15px', fontSize: '0.85rem' }}>
        <button 
          onClick={() => setShowReplyForm(!showReplyForm)}
          style={{ background: 'none', border: 'none', color: '#0066cc', cursor: 'pointer', padding: 0 }}
        >
          Reply
        </button>
        <button 
          onClick={handleDelete}
          style={{ background: 'none', border: 'none', color: '#cc0000', cursor: 'pointer', padding: 0 }}
        >
          Delete
        </button>
      </div>

      {showReplyForm && (
        <form onSubmit={handleReplySubmit} style={{ marginTop: '10px', display: 'flex', flexDirection: 'column', gap: '8px', maxWidth: '500px' }}>
          <div style={{ display: 'flex', gap: '10px', alignItems: 'center' }}>
            <span style={{ fontSize: '0.85rem', color: '#555' }}>Reply as:</span>
            <select 
              value={authorUsername} 
              onChange={(e) => setAuthorUsername(e.target.value)}
              style={{ fontSize: '0.85rem', padding: '4px', borderRadius: '4px', border: '1px solid #ccc' }}
            >
              <option value="alice">alice</option>
              <option value="bob">bob</option>
            </select>
          </div>
          <textarea
            value={replyContent}
            onChange={(e) => setReplyContent(e.target.value)}
            placeholder="Write a reply..."
            rows={3}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc', fontFamily: 'inherit' }}
          />
          <div style={{ display: 'flex', gap: '8px' }}>
            <button 
              type="submit" 
              disabled={isSubmitting}
              style={{ padding: '6px 12px', fontSize: '0.85rem', cursor: 'pointer', borderRadius: '4px', border: 'none', background: '#0066cc', color: '#fff' }}
            >
              {isSubmitting ? 'Replying...' : 'Submit'}
            </button>
            <button 
              type="button" 
              onClick={() => setShowReplyForm(false)}
              style={{ padding: '6px 12px', fontSize: '0.85rem', cursor: 'pointer', borderRadius: '4px', border: '1px solid #ccc', background: '#fff' }}
            >
              Cancel
            </button>
          </div>
        </form>
      )}

      {comment.children && comment.children.length > 0 && (
        <div className="comment-children">
          {comment.children.map((child) => (
            <CommentNode 
              key={child.id} 
              comment={child} 
              postId={postId} 
              onReplyAdded={onReplyAdded}
              onDeleteDone={onDeleteDone}
            />
          ))}
        </div>
      )}
    </div>
  );
};

export const PostPage = () => {
  const { postId } = useParams();
  const id = Number(postId);

  const { data: commentTree, isLoading, error, refetch } = useQuery(getCommentTree, { postId: id });

  const [newCommentContent, setNewCommentContent] = useState('');
  const [authorUsername, setAuthorUsername] = useState('alice');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleCreateComment = async (e) => {
    e.preventDefault();
    if (!newCommentContent.trim()) return;
    setIsSubmitting(true);
    try {
      await createComment({
        postId: id,
        authorUsername,
        content: newCommentContent,
      });
      setNewCommentContent('');
      refetch();
    } catch (err) {
      alert(err.message || 'Failed to create comment');
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isLoading) return <div style={{ padding: '20px' }}>Loading comment tree...</div>;
  if (error) return <div style={{ padding: '20px', color: 'red' }}>Error: {error.message}</div>;

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px' }}>
      <div style={{ marginBottom: '20px' }}>
        <Link to="/" style={{ color: '#0066cc', textDecoration: 'none' }}>&larr; Back to Posts</Link>
      </div>

      <h1 style={{ fontSize: '2rem', marginBottom: '20px', borderBottom: '1px solid #eee', paddingBottom: '10px' }}>
        Post Thread #{id}
      </h1>

      {/* Top Level Comment Form */}
      <div style={{ background: '#f9f9f9', padding: '20px', borderRadius: '8px', marginBottom: '30px', border: '1px solid #eee' }}>
        <h3 style={{ marginTop: 0, marginBottom: '15px' }}>Add a new comment</h3>
        <form onSubmit={handleCreateComment} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <div style={{ display: 'flex', gap: '10px', alignItems: 'center' }}>
            <span style={{ fontSize: '0.9rem', color: '#555' }}>Comment as:</span>
            <select 
              value={authorUsername} 
              onChange={(e) => setAuthorUsername(e.target.value)}
              style={{ fontSize: '0.9rem', padding: '6px', borderRadius: '4px', border: '1px solid #ccc' }}
            >
              <option value="alice">alice</option>
              <option value="bob">bob</option>
            </select>
          </div>
          <textarea
            value={newCommentContent}
            onChange={(e) => setNewCommentContent(e.target.value)}
            placeholder="Write a comment..."
            rows={4}
            style={{ width: '100%', padding: '10px', borderRadius: '4px', border: '1px solid #ccc', fontFamily: 'inherit' }}
          />
          <button 
            type="submit" 
            disabled={isSubmitting}
            style={{ width: 'fit-content', padding: '8px 16px', fontSize: '0.9rem', cursor: 'pointer', borderRadius: '4px', border: 'none', background: '#0066cc', color: '#fff', fontWeight: 'bold' }}
          >
            {isSubmitting ? 'Posting...' : 'Post Comment'}
          </button>
        </form>
      </div>

      {/* Comment Tree */}
      <div>
        <h2 style={{ fontSize: '1.5rem', marginBottom: '20px' }}>Discussion</h2>
        {commentTree && commentTree.length > 0 ? (
          <div className="comment-tree">
            {commentTree.map((comment) => (
              <CommentNode 
                key={comment.id} 
                comment={comment} 
                postId={id} 
                onReplyAdded={refetch}
                onDeleteDone={refetch}
              />
            ))}
          </div>
        ) : (
          <p style={{ color: '#666', fontStyle: 'italic' }}>No comments yet. Be the first to reply!</p>
        )}
      </div>
    </div>
  );
};

