                  >
                    View Discussion &rarr;
                  </Link>
                </li>
              ))}
            </ul>
          ) : (
            posts && <p style={{ color: '#666', fontStyle: 'italic' }}>No posts found. Please run the database seed!</p>
          )}
        </div>
      </main>
    </div>
  );
};
